using System;using System.IO;using System.Linq;using System.Threading;using Musikbox;
class Download63 {
 static int n;static void Check(bool ok,string label){if(!ok)throw new Exception(label);Console.WriteLine("PASS "+label);n++;}
 static void Main(string[] args){string output=Path.Combine(Path.GetFullPath(args[0]),Guid.NewGuid().ToString("N")),exe=Path.GetFullPath(args[1]);Directory.CreateDirectory(output);int lines=0;string result=VideoAudioImport.Download("http://127.0.0.1:8763/local.mp4","mp3",2,output,exe,"/usr/bin/ffmpeg","",()=>{},s=>System.Threading.Interlocked.Increment(ref lines));Check(Directory.GetFiles(result,"*.mp3").Any(p=>MediaMetadata.Read(p).Duration>0),"Berechtigtes eigenes Testvideo über HTTP nach MP3");Check(lines>0,"Fortschrittsrückmeldungen");bool rejected=false;try{VideoAudioImport.Download("http://127.0.0.1:8763/missing.mp4","mp3",2,output,exe,"/usr/bin/ffmpeg","",()=>{},s=>{});}catch{rejected=true;}Check(rejected,"Nicht erreichbare Quelle meldet Fehler");bool cancelled=false;try{VideoAudioImport.Download("http://127.0.0.1:8763/local.mp4","mp3",2,output,exe,"/usr/bin/ffmpeg","",()=>{throw new OperationCanceledException();},s=>{});}catch(OperationCanceledException){cancelled=true;}Check(cancelled,"Abbrechen wird weitergegeben");Check(Directory.GetDirectories(output,".Musikbox-unvollstaendig-*").Length==0,"Fehler und Abbruch räumen Teilergebnisse auf");Console.WriteLine("BESTANDEN: "+n);}
}
